/// <summary>
/// A node of the merchandising hierarchy (REQ-PIM-903). Self-referencing via <c>ParentNode</c>; kept per legal entity.
/// </summary>
public class DYLO_MerchHierarchyNode extends common
{
}

Method.Source:
public void initValue()
{
    super();

    this.Active = NoYes::Yes;
}

public static DYLO_MerchHierarchyNode find(RecId _recId, boolean _forUpdate = false)
{
    DYLO_MerchHierarchyNode node;

    if (_recId)
    {
        node.selectForUpdate(_forUpdate);

        select firstonly node
            where node.RecId == _recId;
    }

    return node;
}

public static DYLO_MerchHierarchyNode findByNodeId(DYLO_MerchNodeId _nodeId, boolean _forUpdate = false)
{
    DYLO_MerchHierarchyNode node;

    if (_nodeId)
    {
        node.selectForUpdate(_forUpdate);

        select firstonly node
            where node.NodeId == _nodeId;
    }

    return node;
}

public static DYLO_MerchHierarchyNode findRoot(boolean _forUpdate = false)
{
    DYLO_MerchHierarchyNode node;

    node.selectForUpdate(_forUpdate);

    select firstonly node
        where node.ParentNode == 0;

    return node;
}

public static boolean exist(DYLO_MerchNodeId _nodeId)
{
    return _nodeId
        && (select firstonly RecId from DYLO_MerchHierarchyNode
                where DYLO_MerchHierarchyNode.NodeId == _nodeId).RecId != 0;
}

public boolean isRoot()
{
    return this.RecId != 0 && this.ParentNode == 0;
}

public boolean hasChildren()
{
    DYLO_MerchHierarchyNode child;

    if (!this.RecId)
    {
        return false;
    }

    select firstonly RecId from child
        where child.ParentNode == this.RecId;

    return child.RecId != 0;
}

public boolean hasProducts()
{
    DYLO_MerchHierarchyProduct product;

    if (!this.RecId)
    {
        return false;
    }

    select firstonly RecId from product
        where product.Node == this.RecId;

    return product.RecId != 0;
}

public boolean isLeaf()
{
    return !this.hasChildren();
}

public DYLO_MerchHierarchyNode parentNode()
{
    return DYLO_MerchHierarchyNode::find(this.ParentNode);
}

/// <summary>
/// Initializes a new child node from its parent node.
/// </summary>
public void initFromParent(DYLO_MerchHierarchyNode _parent)
{
    this.ParentNode                 = _parent.RecId;
    this.HierarchyLevel             = _parent.HierarchyLevel + 1;
    this.SortOrder                  = DYLO_MerchHierarchyManager::nextSortOrder(_parent.RecId);
    this.EffectiveMinGrossMarginPct = _parent.EffectiveMinGrossMarginPct;
    this.InheritedFromNode          = _parent.InheritedFromNode;
}

/// <summary>
/// Calculates the level and the effective minimum gross margin from the parent node.
/// A node's own value (other than 0) wins; 0 inherits the nearest parent's effective value.
/// </summary>
public void calcFromParent()
{
    DYLO_MerchHierarchyNode parent = this.parentNode();

    if (parent.RecId)
    {
        this.HierarchyLevel = parent.HierarchyLevel + 1;

        if (this.MinGrossMarginPct != 0)
        {
            this.EffectiveMinGrossMarginPct = this.MinGrossMarginPct;
            this.InheritedFromNode          = this.RecId;
        }
        else
        {
            this.EffectiveMinGrossMarginPct = parent.EffectiveMinGrossMarginPct;
            this.InheritedFromNode          = parent.InheritedFromNode;
        }
    }
    else
    {
        this.HierarchyLevel             = 1;
        this.EffectiveMinGrossMarginPct = this.MinGrossMarginPct;
        this.InheritedFromNode          = this.RecId;
    }
}

public void insert()
{
    ttsbegin;

    this.calcFromParent();

    super();

    if (!this.InheritedFromNode)
    {
        // The node's own value is effective: point to the node itself now that its RecId is known.
        this.selectForUpdate(true);
        this.InheritedFromNode = this.RecId;
        this.doUpdate();
    }

    ttscommit;
}

public void update()
{
    DYLO_MerchHierarchyNode orig = this.orig();
    boolean                 recalcSubtree;

    ttsbegin;

    this.calcFromParent();

    recalcSubtree = orig.ParentNode                 != this.ParentNode
                 || orig.MinGrossMarginPct          != this.MinGrossMarginPct
                 || orig.EffectiveMinGrossMarginPct != this.EffectiveMinGrossMarginPct
                 || orig.InheritedFromNode          != this.InheritedFromNode
                 || orig.HierarchyLevel             != this.HierarchyLevel;

    super();

    if (recalcSubtree)
    {
        DYLO_MerchHierarchyManager::recalcSubtree(this);
    }

    ttscommit;
}

public boolean validateWrite()
{
    boolean                 ret = super();
    DYLO_MerchHierarchyNode parent;
    DYLO_MerchHierarchyNode otherRoot;

    if (ret)
    {
        if (!this.ParentNode)
        {
            select firstonly RecId from otherRoot
                where otherRoot.ParentNode == 0
                   && otherRoot.RecId      != this.RecId;

            if (otherRoot.RecId)
            {
                ret = checkFailed("@DYLOExtensions:MerchHierOnlyOneRoot");
            }
        }
        else
        {
            parent = DYLO_MerchHierarchyNode::find(this.ParentNode);

            if (!parent.RecId || parent.RecId == this.RecId)
            {
                ret = checkFailed("@DYLOExtensions:MerchHierParentInvalid");
            }
            else if (!this.RecId)
            {
                if (parent.hasProducts())
                {
                    ret = checkFailed(strFmt("@DYLOExtensions:MerchHierParentHasProducts", parent.NodeId));
                }

                if (!parent.Active)
                {
                    ret = checkFailed(strFmt("@DYLOExtensions:MerchHierParentInactive", parent.NodeId));
                }
            }
            else if (this.ParentNode != this.orig().ParentNode)
            {
                ret = DYLO_MerchHierarchyManager::validateNewParent(this, parent) && ret;
            }
        }

        if (this.MinGrossMarginPct < 0 || this.MinGrossMarginPct > 100)
        {
            ret = checkFailed("@DYLOExtensions:MerchHierMarginRange");
        }
    }

    return ret;
}

public boolean validateDelete()
{
    boolean ret = super();

    if (ret)
    {
        if (!this.ParentNode)
        {
            ret = checkFailed("@DYLOExtensions:MerchHierRootNoDelete");
        }

        if (this.hasChildren())
        {
            ret = checkFailed(strFmt("@DYLOExtensions:MerchHierHasChildren", this.NodeId));
        }

        if (this.hasProducts())
        {
            ret = checkFailed(strFmt("@DYLOExtensions:MerchHierHasProducts", this.NodeId));
        }
    }

    return ret;
}

/// <summary>
/// The node as "NodeId - Name".
/// </summary>
public display Description255 nodeDisplay()
{
    if (!this.RecId && !this.NodeId)
    {
        return '';
    }

    return strFmt("@DYLOExtensions:MerchHierNodeText", this.NodeId, this.Name);
}

/// <summary>
/// The text of the node in the tree: "NodeId - Name", followed by "(inactive)" for an inactive node.
/// </summary>
public Description255 treeText()
{
    Description255 text = this.nodeDisplay();

    if (this.RecId && !this.Active)
    {
        text = strFmt("@DYLOExtensions:MerchHierInactiveText", text);
    }

    return text;
}

public display Description255 parentNodeDisplay()
{
    DYLO_MerchHierarchyNode parent = this.parentNode();

    if (!parent.RecId)
    {
        return '';
    }

    return strFmt("@DYLOExtensions:MerchHierParentText", parent.NodeId, parent.Name, parent.HierarchyLevel);
}

public display Description255 inheritedFromDisplay()
{
    return DYLO_MerchHierarchyNode::find(this.InheritedFromNode).nodeDisplay();
}

public display HcmWorkerName categoryManagerName()
{
    return this.CategoryManager ? HcmWorker::find(this.CategoryManager).name() : '';
}

public display Counter rollupProductCount()
{
    return DYLO_MerchHierarchyManager::rollupProductCount(this.RecId);
}
